-- seed_sample_products.sql — 카드별 샘플 쿠팡 제품(플레이스홀더)
-- 어드민 앱의 '샘플 데이터 넣기'와 동일한 데이터. 대시보드 SQL 에디터에서 실행 가능.
-- 딥링크=쿠팡 검색 URL(임시), 썸네일=임의 이미지(picsum). 실제 파트너스 링크로 교체 필요.
-- 멱등: coupang_pid 접두 SAMPLE- 로 upsert(중복 실행 안전, 실데이터 미침범).

on conflict (symptom_id, coupang_pid) do update set
  title = excluded.title, deeplink = excluded.deeplink, image_url = excluded.image_url,
  price = excluded.price, rating = excluded.rating, rank_index = excluded.rank_index,
  is_active = excluded.is_active;
